//! Minimal, bounded multipart/form-data parser for image uploads.
//!
//! It intentionally supports only the subset generated by the upload form:
//! one file field and a few text fields.  There is no nested multipart, no
//! filename* decoding and no unbounded part count.

/// Hard upper bound on the number of parts in one form.
pub const MAX_PARTS: usize = 64;
const MAX_HEADER_BYTES: usize = 8 * 1024;

/// One part of a `multipart/form-data` body.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Part {
    /// Form field name from `Content-Disposition`.
    pub name: String,
    /// Client-supplied file name, when the part is a file.
    pub filename: Option<String>,
    /// `Content-Type` of the part, when supplied.
    pub content_type: Option<String>,
    /// Raw part body.
    pub data: Vec<u8>,
}

/// Parse a bounded `multipart/form-data` body.
///
/// `max_parts` is clamped to `1..=MAX_PARTS`. Nested multipart, `filename*`
/// decoding and unbounded part counts are deliberately unsupported.
pub fn parse(content_type: &str, body: &[u8], max_parts: usize) -> Result<Vec<Part>, String> {
    let boundary = boundary_from_content_type(content_type)
        .ok_or_else(|| "missing multipart boundary".to_string())?;
    if boundary.is_empty()
        || boundary.len() > 70
        || boundary.bytes().any(|b| b == b'\r' || b == b'\n' || b == 0)
    {
        return Err("invalid multipart boundary".into());
    }
    let limit = max_parts.clamp(1, MAX_PARTS);
    let mut delimiter = Vec::with_capacity(boundary.len() + 2);
    delimiter.extend_from_slice(b"--");
    delimiter.extend_from_slice(boundary.as_bytes());

    let Some(first) = find(body, &delimiter) else {
        return Err("multipart boundary not found".into());
    };
    let mut pos = first + delimiter.len();
    if body[pos..].starts_with(b"--") {
        return Ok(Vec::new());
    }
    let mut parts = Vec::new();
    while parts.len() < limit {
        if body[pos..].starts_with(b"\r\n") {
            pos += 2;
        } else if body[pos..].starts_with(b"\n") {
            pos += 1;
        } else {
            return Err("malformed multipart delimiter".into());
        }
        let Some(header_rel) = find(&body[pos..], b"\r\n\r\n") else {
            return Err("truncated multipart headers".into());
        };
        if header_rel > MAX_HEADER_BYTES {
            return Err("multipart headers too large".into());
        }
        let header_end = pos + header_rel;
        let headers = &body[pos..header_end];
        let data_start = header_end + 4;
        let mut next_marker = Vec::with_capacity(delimiter.len() + 2);
        next_marker.extend_from_slice(b"\r\n");
        next_marker.extend_from_slice(&delimiter);
        let Some(data_rel) = find(&body[data_start..], &next_marker) else {
            return Err("truncated multipart body".into());
        };
        let data_end = data_start + data_rel;
        let mut part = parse_headers(headers)?;
        part.data = body[data_start..data_end].to_vec();
        parts.push(part);
        pos = data_end + next_marker.len();
        if body[pos..].starts_with(b"--") {
            return Ok(parts);
        }
    }
    Err("too many multipart parts".into())
}

fn boundary_from_content_type(value: &str) -> Option<String> {
    let mut pieces = value.split(';');
    let mime = pieces.next()?.trim();
    if !mime.eq_ignore_ascii_case("multipart/form-data") {
        return None;
    }
    for piece in pieces {
        let Some((key, value)) = piece.split_once('=') else {
            continue;
        };
        if key.trim().eq_ignore_ascii_case("boundary") {
            let value = value.trim();
            let value = value
                .strip_prefix('"')
                .and_then(|v| v.strip_suffix('"'))
                .unwrap_or(value);
            return Some(value.to_string());
        }
    }
    None
}

fn parse_headers(raw: &[u8]) -> Result<Part, String> {
    let text = String::from_utf8_lossy(raw);
    let mut name = String::new();
    let mut filename = None;
    let mut content_type = None;
    for line in text.split("\r\n") {
        let Some((header, value)) = line.split_once(':') else {
            continue;
        };
        if header.eq_ignore_ascii_case("content-disposition") {
            for (key, value) in header_parameters(value) {
                if key.eq_ignore_ascii_case("name") {
                    name = value;
                } else if key.eq_ignore_ascii_case("filename") {
                    filename = Some(value);
                }
            }
        } else if header.eq_ignore_ascii_case("content-type") {
            content_type = Some(value.trim().to_string());
        }
    }
    if name.is_empty() {
        return Err("multipart part has no name".into());
    }
    Ok(Part {
        name,
        filename,
        content_type,
        data: Vec::new(),
    })
}

/// Split a `Content-Disposition` value into its parameters.
///
/// `;` separators inside a quoted value are part of the value, so a file named
/// `report;final.png` keeps its extension. Quoted values are unquoted and
/// `\"`/`\\` are unescaped. Control characters never reach the caller as part
/// of a header separator: they stay inside the value and are stripped when the
/// file name is sanitised.
fn header_parameters(value: &str) -> Vec<(String, String)> {
    let mut parts: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut quoted = false;
    let mut escaped = false;
    for ch in value.chars() {
        if escaped {
            current.push(ch);
            escaped = false;
            continue;
        }
        match ch {
            '\\' if quoted => {
                current.push(ch);
                escaped = true;
            }
            '"' => {
                quoted = !quoted;
                current.push(ch);
            }
            ';' if !quoted => {
                parts.push(std::mem::take(&mut current));
            }
            _ => current.push(ch),
        }
    }
    parts.push(current);
    let mut out = Vec::new();
    for part in parts.into_iter().skip(1) {
        let Some((key, value)) = part.split_once('=') else {
            continue;
        };
        let value = value.trim();
        let value = value
            .strip_prefix('"')
            .and_then(|rest| rest.strip_suffix('"'))
            .unwrap_or(value)
            .replace("\\\"", "\"")
            .replace("\\\\", "\\");
        out.push((key.trim().to_string(), value));
    }
    out
}

fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || haystack.len() < needle.len() {
        return None;
    }
    haystack
        .windows(needle.len())
        .position(|window| window == needle)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::testutil::Rng;

    #[test]
    fn parses_a_simple_form() {
        let body = b"--x\r\nContent-Disposition: form-data; name=\"wpText\"\r\n\r\nhello\r\n--x\r\nContent-Disposition: form-data; name=\"file\"; filename=\"a.png\"\r\nContent-Type: image/png\r\n\r\nPNGDATA\r\n--x--\r\n";
        let parts = parse("multipart/form-data; boundary=x", body, 10).unwrap();
        assert_eq!(parts.len(), 2);
        assert_eq!(parts[0].name, "wpText");
        assert_eq!(parts[0].data, b"hello");
        assert_eq!(parts[1].filename.as_deref(), Some("a.png"));
        assert_eq!(parts[1].data, b"PNGDATA");
    }

    #[test]
    fn rejects_bad_boundaries_and_truncation() {
        assert!(parse("text/plain", b"", 10).is_err());
        assert!(parse("multipart/form-data; boundary=", b"", 10).is_err());
        assert!(parse(
            "multipart/form-data; boundary=x",
            b"--x\r\nContent-Disposition: form-data; name=\"a\"\r\n",
            10
        )
        .is_err());
        assert!(parse(
            "multipart/form-data; boundary=x",
            b"--x\r\nContent-Disposition: form-data; name=\"a\"\r\n\r\nvalue",
            10
        )
        .is_err());
    }

    #[test]
    fn quoted_parameters_keep_semicolons_and_escapes() {
        let body = b"--x\r\nContent-Disposition: form-data; name=\"attachment[]\"; filename=\"report;final.png\"\r\n\r\nDATA\r\n--x--\r\n";
        let parts = parse("multipart/form-data; boundary=x", body, 10).unwrap();
        assert_eq!(parts[0].name, "attachment[]");
        assert_eq!(parts[0].filename.as_deref(), Some("report;final.png"));

        let body = b"--x\r\nContent-Disposition: form-data; name=\"a\"; filename=\"say \\\"hi\\\".png\"\r\n\r\nDATA\r\n--x--\r\n";
        let parts = parse("multipart/form-data; boundary=x", body, 10).unwrap();
        assert_eq!(parts[0].filename.as_deref(), Some("say \"hi\".png"));
    }

    #[test]
    fn fuzz_multipart_part_counts_and_huge_headers() {
        fn body(parts: usize) -> Vec<u8> {
            let mut body = Vec::new();
            for index in 0..parts {
                body.extend_from_slice(
                    format!(
                        "--x\r\nContent-Disposition: form-data; name=\"f{}\"\r\n\r\nv{}\r\n",
                        index, index
                    )
                    .as_bytes(),
                );
            }
            body.extend_from_slice(b"--x--\r\n");
            body
        }
        // 0, 1, 64 and 65 parts stay bounded.
        assert!(parse("multipart/form-data; boundary=x", b"--x--\r\n", 10)
            .unwrap()
            .is_empty());
        assert_eq!(
            parse("multipart/form-data; boundary=x", &body(1), 10)
                .unwrap()
                .len(),
            1
        );
        assert_eq!(
            parse(
                "multipart/form-data; boundary=x",
                &body(MAX_PARTS - 1),
                1_000
            )
            .unwrap()
            .len(),
            MAX_PARTS - 1
        );
        assert_eq!(
            parse("multipart/form-data; boundary=x", &body(MAX_PARTS), 1_000)
                .unwrap()
                .len(),
            MAX_PARTS
        );
        // One part over the cap is an error, never a partial silent success.
        assert!(parse("multipart/form-data; boundary=x", &body(65), 1_000).is_err());

        // Huge headers, duplicate names, unquoted parameters, NUL and a
        // truncated final boundary are all handled without panicking.
        let mut huge = b"--x\r\nContent-Disposition: form-data; name=\"a\"\r\nX-Pad: ".to_vec();
        huge.extend_from_slice(&vec![b'p'; 9 * 1024]);
        huge.extend_from_slice(b"\r\n\r\nvalue\r\n--x--\r\n");
        assert!(parse("multipart/form-data; boundary=x", &huge, 10).is_err());

        let duplicate = b"--x\r\nContent-Disposition: form-data; name=\"a\"\r\n\r\n1\r\n\
                          --x\r\nContent-Disposition: form-data; name=a\r\n\r\n2\r\n--x--\r\n";
        let parts = parse("multipart/form-data; boundary=x", duplicate, 10).unwrap();
        assert_eq!(parts.len(), 2);
        assert_eq!(parts[0].name, "a");
        assert_eq!(parts[1].name, "a");

        let nul = b"--x\r\nContent-Disposition: form-data; name=\"a\0b\"\r\n\r\n1\r\n--x--\r\n";
        let _ = parse("multipart/form-data; boundary=x", nul, 10);

        let truncated = b"--x\r\nContent-Disposition: form-data; name=\"a\"\r\n\r\nvalue";
        assert!(parse("multipart/form-data; boundary=x", truncated, 10).is_err());
    }

    #[test]
    fn fuzz_multipart_parser_never_panics() {
        let mut rng = Rng::new(0x6d75_0001);
        let alphabet = b"--x\r\nContent-Disposition: form-data; name=\"a\"; filename=\"f\"; boundary=;0123456789abcdef\"'\\\0";
        for _ in 0..3_000 {
            let len = rng.below(512);
            let body = rng.ascii(len, alphabet).into_bytes();
            let ct = if rng.below(2) == 0 {
                "multipart/form-data; boundary=x".to_string()
            } else {
                format!("multipart/form-data; boundary={}", rng.ascii(8, alphabet))
            };
            if let Ok(parts) = parse(&ct, &body, 20) {
                assert!(parts.len() <= MAX_PARTS);
                for part in parts {
                    assert!(!part.name.is_empty());
                    assert!(part.data.len() <= body.len());
                }
            }
        }
    }
}
